$strSQLSelect = "SELECT distinct 
app.geo_lote_31983.uid, app.geo_lote_31983.chave_lote 
FROM app.geo_lote_31983 
where app.geo_lote_31983.chave_lote = '".$params["txt"]."'";

$rsExists = db_query($strSQLSelect,$conn);
$data = db_fetch_array($rsExists);

if($data) {
	$jsonDataParamStyle =  array( "binValues" => [ array("alpha"=> 1, "color" => "#ff0000" )] );
	$jsonDataParamData = array( "workspace" => "app", "layerName" => "geo_lote_31983", "title"=> "Seleção Lote", "style" => $jsonDataParamStyle);
  $jsonDataParamFilter = array( "fields" => "uid", "where" => "\"uid\" = {$data["uid"]}");
	$jsonData = array("message"=> "Localizado", "data" => [$jsonDataParamData , $jsonDataParamFilter]);

	$result["txt"] = json_encode($jsonData);}
else {
	$jsonData = array("message"=> "Não localizado no mapa.", "data" => null);
  $result["txt"] = json_encode($jsonData);
};

